#ifndef STADIUM_H
#define STADIUM_H
/*
 * Stadium crowd (pure, host tested): which stand tile sits in which cell, per side. The motion tables and the tile pairs are
 * generated by tools/build_stadium_sprites.py (build/gen/stadium_motion.h, small: no per-frame tables); this file only steps the
 * two sides and looks the tiles up. Tile numbers are relative to STADIUM_TILE_BASE (0 = blank).
 * Side 0 = columns 0..9 (player 1), side 1 = columns 10..20. Each side has a mode and its own local time t (one step = one
 * animation frame of the approved art, STADIUM_STEP_FRAMES game frames).
 */
#include <stdint.h>

#define STADIUM_COLS 21            /* stand columns (336 px) */
#define STADIUM_FLING_COLS 23      /* Gum Fling plane: 368 px, so the 1/4 speed scroll (0..48 px) never reaches the seam */
#define STADIUM_NEAR_ROWS 3
#define STADIUM_FAR_ROWS 2
#define STADIUM_STEP_FRAMES 3      /* game frames per animation step (20 Hz) */
#define STADIUM_SIDE_COLS 10       /* columns 0..9 belong to side 0 */
#define STADIUM_DIGITS 4           /* scoreboard: P1 tens, P1 ones, P2 tens, P2 ones */
#define STADIUM_FLING_SCROLL_MAX 192   /* field scroll range of the Fling field (512 px field, 320 px screen) */
#define STADIUM_FLING_SHIFT 2      /* stand follows the field at 1/4 speed */
enum { STADIUM_IDLE, STADIUM_CHEER, STADIUM_WAVE, STADIUM_WINNER, STADIUM_LOSER };

typedef struct { uint8_t mode[2]; uint16_t t[2]; uint8_t score[2]; } Stadium;
typedef struct { uint16_t top, bot; } StadiumCell;

void stadium_reset(Stadium *s);
/* A score that rose starts the cheer of its side (jump, then idle again); a lower or equal score only stores. Capped at 99. */
void stadium_set_scores(Stadium *s, uint8_t p1, uint8_t p2);
/* Both sides roll the wave once. */
void stadium_wave(Stadium *s);
/* End of the event: winner 0 or 1 rolls its wave forever and the other side slumps; -1 (draw) cheers on both sides. */
void stadium_finish(Stadium *s, int winner);
/* One animation step. */
void stadium_step(Stadium *s);
/* The head-room and seat tile of near cell (row 0..2, column) / far cell (row 0..1, column; row 0 = the upper far row). */
StadiumCell stadium_near(const Stadium *s, int row, int col, int storm);
StadiumCell stadium_far(const Stadium *s, int row, int col);
void stadium_far_warm(int row, int col);   /* fills the idle result of one far cell for every phase: spreads the first lookups over the load frames */
/* The four scoreboard digit tiles (tens/ones P1, tens/ones P2). */
void stadium_digit_tiles(const Stadium *s, uint16_t out[STADIUM_DIGITS]);
/* Stand x offset in px (0 .. -48) for a Gum Fling field scroll. */
int stadium_fling_x(int field_scroll);
/* Checksum over every cell of every mood, mode and frame; must equal ST_GOLDEN of the exporter's Python run. */
uint32_t stadium_golden(void);
uint32_t stadium_golden_expected(void);
#endif
